        brkstack[nloop] = a; cntstack[nloop] = c;
        brkdep[nloop] = bdepth; cntdep[nloop] = bdepth; nloop = nloop + 1;
        stmt();
        nloop = nloop - 1;
        elab("L", c); es(":\n");
        need(tidx("while", 5), "while");
        need(tidx("(", 1), "(");
        expr(); loadval(); ftruthy();
        need(tidx(")", 1), ")");
        need(tidx(";", 1), ";");
        elab("  @ctrl.jumpz r0, L", a); ec(10);
        elab("  @ctrl.jump L", top); ec(10);
