        if (a[3] == SK_IMM) { a_movimm(a[0], a[1], 0); return 1; }
        if (a[3] == SK_REG) { ow(0xAA0003E0 | (a[1] << 16) | a[0]); return 1; }
        if (a[3] == SK_ADDR) { a_adrp_add(a[0], pc, a[1] + bk_shift); return 1; }
