        ow(0xF9400000 | (A_IP1 << 5) | A_IP1);
        ow(0x8B000000 | (a[1] << 16) | (3 << 10) | (A_IP1 << 5) | A_IP1);
        ow(0xF9400000 | (A_IP1 << 5) | a[0]);
        return 1;
